/// <reference types="electron-vite/node" />
import icoPath from "../../build/icon.ico?asset";
import pngPath from "../../build/icons/512x512.png?asset";

/**
 * The window icon (the Slabyrinth logo, generated by scripts/make-icons.ts). electron-vite copies
 * both files into out/main and resolves them next to the bundle, so the same path works in dev and
 * inside the packaged asar. Windows takes the multi-size .ico (crisp 16/24/32 px variants for the
 * title bar and taskbar); Linux takes the 512 px PNG (_NET_WM_ICON / Wayland window icon).
 * Without it, Linux windows and dev runs (electron.exe) show Electron's default icon.
 */
export function windowIconPath(platform: NodeJS.Platform = process.platform): string {
  return platform === "win32" ? icoPath : pngPath;
}
